function plannedEnglishContent(){
  const row=englishLessonPlan()?(level===1?englishA2Data.content:englishA1Content)[unit]:null;
  if(!row)return null;
  const lines=pairs=>pairs.map(([text,pt])=>({text,pt}));
  return {reading:lines(row[0]),dialogue:lines(row[1]),pronunciation:row[2],grammar:row[3]};
}
const englishA1GrammarPatterns=[
  /Can I have/i,/\ban\b/i,/^(?:go straight|yes\. cross|cross)/i,/\b(?:my|your)\b/i,/\bthere is\b/i,
  /would like/i,/\btwo (?:rolls|muffins|cookies)/i,/\bcan i\b/i,/\bat (?:seven|eight)\b/i,/one ticket/i,
  /\b(?:this|these) tickets?\b/i,/\blive (?:in|on|near)\b/i,/\bthere are\b/i,/\bis there\b/i,/next to|across from|by the/i,
  /before|after/i,/what time/i,/\b(?:am|is|are) (?:sending|typing|walking|going|waiting|doing|reading)\b/i,/\bwho is\b|this is/i,/\b(?:i am|this is|you are|we are)\b/i,
  /\bon friday\b/i,/table for/i,/\b(?:that|those)\b/i,/\bsome\b|glasses of water/i,/where can i sit/i,
  /do you like|i do\b/i,/do you have/i,/^(?:write|use|put|yes\. write)/i,/in (?:her|your|my) notebook|on the first page/i,/\b(?:we|they)\b/i,
  /^I (?:turn|check|look|use|start)\b/i,/\b(?:he|she) (?:uses|writes|studies|puts)\b/i,/do not|stay on/i,/small town|quiet street|white table/i,/want(?:s)? to/i,
  /what time does/i,/how long/i,/which/i,/must/i,/\b(?:first|second|third) row\b/i,
  /can we/i,/the next train/i,/\bhas\b|\bi have\b/i,/\bunder\b/i,/\bon the (?:first|second) floor\b/i,
  /please (?:ask|write)/i,/\b(?:am|are|is) (?:early|late|on time)\b/i,/\bcannot\b|\bcan i\b/i,/would you like to/i,/\b(?:and|but)\b/i
];
function plannedEnglishExamples(content){
  const all=[...content.dialogue,...content.reading];
  const pattern=(level===1?englishA2Data.patterns:englishA1GrammarPatterns)[unit];
  const matching=all.filter(line=>pattern.test(line.text));
  return [...new Map([...matching,...all].map(line=>[line.text,line])).values()].slice(0,2);
}
function renderCompletedEnglishGrammar(plan,content,photo,used){
  const [question,correct,wrong,translation,reason]=content.grammar;
  const options=unit%2?[wrong,correct]:[correct,wrong];
  const choices='<section class="grammar-choice"><h4>Complete a frase</h4><div class="grammar-choice-case">'+nativeText(question,'p')+
    '<p class="meta" lang="pt-BR">'+clean(translation)+'</p><div class="controls">'+
    options.map(option=>'<button type="button" data-grammar-choice="'+clean(option)+'">'+nativeText(option)+'</button>').join('')+
    '</div><p class="grammar-choice-status" role="status" data-correct="'+clean(correct)+'" data-reason="'+clean(reason)+'"></p></div></section>';
  const examples=plannedEnglishExamples(content).map(({text,pt})=>[text,pt]);
  return '<article class="lesson-card">'+lessonPhotoFrame(photo,'a1-block-photo')+
    renderGrammarRule(plan.grammar,plan.goal,
    'Observe a posição da parte destacada no exercício. Use o contexto e a tradução para conferir a sua escolha.',
    examples,{},used,choices)+'</article>';
}
function buildCompletedEnglishLesson(plan,content){
  const [first,second]=plan.words;
  const vocabulary={
    word:first[0],expression:second[0],
    wordExample:plannedEnglishWordExample(first[0],content),
    expressionExample:plannedEnglishWordExample(second[0],content),
    meanings:[first[1],second[1]]
  };
  const focus=plannedEnglishExamples(content)[0];
  const sample=vocabulary.wordExample||focus;
  return {vocabulary,practiceContent:content,cardPhotos:new Set([plan.file]),grammarTitle:plan.grammar,
    tasks:{word:vocabulary.word,phrase:vocabulary.expression,sentence:sample.text,translation:sample.pt}};
}
function plannedEnglishWordExample(term,content){
  const needle=term.replace(/[.…?!]+$/u,'');
  const example=[...content.reading,...content.dialogue].find(line=>Boolean(wordUseGap(line.text,needle)));
  const supplement=(level===1?englishA2Data.extras:englishA1ExtraWordExamples)[unit]?.[term];
  return example||(supplement?{text:supplement[0],pt:supplement[1]}:null);
}
function renderCompletedEnglishVocabulary(plan,content,photo){
  return '<section class="lesson-plan-card" aria-labelledby="planVocabularyTitle"><h3 id="planVocabularyTitle">Vocabulário da lição</h3>'+
    lessonPhotoFrame(photo,'a1-block-photo')+'<dl class="lesson-plan-words">'+
    plan.words.map(([term,meaning])=>{
      const example=plannedEnglishWordExample(term,content);
      return '<div><dt>'+nativeText(term)+lessonPlayButton(term,{compact:true})+'</dt><dd>'+clean(meaning)+
        (example?'<p>'+nativeText(example.text)+lessonPlayButton(example.text,{compact:true})+'</p><p lang="pt-BR">'+clean(example.pt)+'</p>':'')+'</dd></div>';
    }).join('')+'</dl></section>';
}
function renderCompletedEnglishScene(plan,content){
  const phrase=content.dialogue[6];
  const reply=content.dialogue[7];
  return '<section class="lesson-card" data-playback-block><h3>'+clean(plan.title)+'</h3><p>Ouça o último par de falas. Perceba qual informação a resposta confirma e diga que pergunta você faria em seguida.</p>'+
    sectionPlayButton('closing-exchange','Ouvir o final da conversa')+
    lessonLinesMarkup([phrase,reply],'dialogue')+'</section>';
}
function renderCompletedEnglishRoleplay(plan,content){
  const [prompt,answer]=content.grammar;
  const template=prompt.replace('___',answer);
  const secondTemplate=plannedEnglishExamples(content)[0].text.replace(/\p{L}+(?=[.?!]?$)/u,'…');
  const reply=content.dialogue[1];
  const writing=contextualRoleplayDraft();
  return '<section class="scene-roleplay" aria-labelledby="roleplayTitle"><h4 id="roleplayTitle">Faça uma versão sua</h4>'+
    '<p>Imagine que você está na cena “'+clean(plan.title)+'”. Use uma das ideias abaixo, troque um detalhe e confira se a sua fala ainda faz sentido.</p>'+
    '<div class="roleplay-writing"><p><strong>Molde 1</strong> '+nativeText(prompt)+'</p><p><strong>Molde 2</strong> '+nativeText(secondTemplate)+'</p>'+
    '<p class="meta">Dica: mantenha o padrão de '+clean(plan.grammar)+' e mude uma pessoa, um objeto, um local ou um horário que faça sentido.</p>'+
    '<label for="roleplayDraft">Escreva sua fala</label>'+writing+
    '<details class="roleplay-model"><summary>Ouvir exemplos de referência</summary>'+nativeText(template,'p')+lessonPlayButton(template,{compact:true})+
    nativeText(reply.text,'p')+lessonPlayButton(reply.text,{compact:true})+'<p lang="pt-BR">'+clean(reply.pt)+'</p></details></div></section>';
}
function contextualRoleplayDraft(){
  return '<textarea id="roleplayDraft" rows="3" lang="en-US" dir="auto">'+clean(roleplayDrafts.get(lessonHash(unit))||'')+'</textarea>';
}

